example.code:
sensor:
  - platform: template
    name: TL VWC (raw)
    id: tl_vwc_raw
    unit_of_measurement: "%"
    accuracy_decimals: 2
    update_interval: 30s
    lambda: |-
      float e = id(tl_eps_b).state;
      if (isnan(e) || e <= 0) return NAN;
      float theta = (5.5728e-6f*e*e*e) + (-6.40228e-4f*e*e)
                  + (2.98804e-2f*e) + 2.14996e-2f;
      float pct = theta * 100.0f;
      if (pct < 0) pct = 0;
      if (pct > 100) pct = 100;
      return pct;

  # Keep the correction as its own entity so the raw value stays auditable.
  # 0.806 is a provisional one-point scale - replace with your own regression.
  - platform: template
    name: TL VWC (aligned to TEROS-12)
    unit_of_measurement: "%"
    accuracy_decimals: 2
    update_interval: 30s
    lambda: |-
      float x = id(tl_vwc_raw).state;
      if (isnan(x)) return NAN;
      return 0.806f * x;
